import 'package:kiln_core/kiln_core.dart';

/// Where the Firebase project configuration comes from.
enum FirebaseOptionsSource {
  /// `lib/firebase_options.dart` generated by the FlutterFire CLI.
  generated,

  /// `FirebaseOptions` assembled by the application itself.
  explicit,
}

/// Local ports used by the Firebase Emulator Suite.
final class FirebaseEmulatorPorts {
  const FirebaseEmulatorPorts({
    this.auth = 9099,
    this.firestore = 8080,
    this.storage = 9199,
  });

  final int auth;
  final int firestore;
  final int storage;
}

/// Typed Firebase settings rendered from the install prompts.
final class FirebaseConfig {
  const FirebaseConfig({
    this.optionsSource = FirebaseOptionsSource.{{options_source}},
    this.firebaseOptionsPath = '{{{firebase_options_path}}}',
    this.emulatorHost = '{{{emulator_host}}}',
    this.useEmulatorInDevelopment = {{use_emulator_in_development}},
    this.ports = const FirebaseEmulatorPorts(),
  });

  /// Defaults produced by the prompts recorded in `extension.yaml`.
  static const defaults = FirebaseConfig();

  final FirebaseOptionsSource optionsSource;

  /// Location reported by the manual step check and used in documentation.
  final String firebaseOptionsPath;

  final String emulatorHost;
  final bool useEmulatorInDevelopment;
  final FirebaseEmulatorPorts ports;

  /// Whether [flavor] must talk to the local Emulator Suite.
  ///
  /// Only the development flavor is redirected so staging and production
  /// builds can never reach localhost by accident.
  bool shouldUseEmulator(AppFlavor flavor) {
    return useEmulatorInDevelopment && flavor == AppFlavor.development;
  }

  FirebaseConfig copyWith({
    FirebaseOptionsSource? optionsSource,
    String? firebaseOptionsPath,
    String? emulatorHost,
    bool? useEmulatorInDevelopment,
    FirebaseEmulatorPorts? ports,
  }) {
    return FirebaseConfig(
      optionsSource: optionsSource ?? this.optionsSource,
      firebaseOptionsPath: firebaseOptionsPath ?? this.firebaseOptionsPath,
      emulatorHost: emulatorHost ?? this.emulatorHost,
      useEmulatorInDevelopment:
          useEmulatorInDevelopment ?? this.useEmulatorInDevelopment,
      ports: ports ?? this.ports,
    );
  }
}
